def random_unitary(dim, seed=None):
    if dim == 0 or not math.log2(dim).is_integer():
        raise QiskitError("Desired unitary dimension not a positive power of 2.")
    matrix = np.zeros([dim, dim], dtype=complex)
    for j in range(dim):
        if j == 0:
            a = random_state(dim, seed)
        else:
            a = random_state(dim)
        matrix[:, j] = np.copy(a)
        # Gram-Schmidt Orthogonalize
        i = j - 1
        while i >= 0:
            dc = np.vdot(matrix[:, i], a)
            matrix[:, j] = matrix[:, j] - dc * matrix[:, i]
            i = i - 1
        # normalize matrix[:, j]
        matrix[:, j] = matrix[:, j] * (1.0 / np.sqrt(np.vdot(matrix[:, j], matrix[:, j])))
    return Operator(matrix)

So it generates a random unitary matrix of dimension dim (must be power of 2). It uses random_state to generate random complex vectors, then orthogonalizes them via Gram-Schmidt, normalizes, and returns an Operator object.

