def _einsum_matmul (cls,tensor,mat,indices,shift = 0,right_mul = False):
    rank = tensor.ndim
    rank_mat = mat.ndim
    if rank_mat % 2 != 0: raise QiskitError ("Contracted matrix must have an even number of indices.")
    # Get einsum indices for tensor indices_tensor = list (range (rank))
    for j,index in enumerate (indices):
        indices_tensor [ index + shift ] = rank + j
    # Get einsum indces for mat mat_contract = list (reversed (range (rank,rank + len (indices))))
    mat_free = [ index + shift for index in reversed (indices)]
    if right_mul:
