def __truncate (self,line_arr,max_width):
    def is_space (chunk):
        return all ([ True if i == ' ' else False for i in chunk ])
    def is_empty (chunks,markups):
        result = [ ]
        for chunk in chunks:
            if chunk in markups:
                result.append (True)
            elif is_space (chunk):
                result.append (True)
            else:
                result.append (False)
